export interface JSONObject {
  [key: string]: JSONValue;
}

type ClassInstance = any;

export type SerializableJSONValue =
  | Symbol
  | Set<SuperJSONValue>
  | Map<SuperJSONValue, SuperJSONValue>
  | undefined
  | bigint
  | Date
  | ClassInstance
  | RegExp;

export type SuperJSONValue =
  | JSONValue
  | SerializableJSONValue
  | SuperJSONArray
  | SuperJSONObject;

export interface SuperJSONArray extends Array<SuperJSONValue> {}

export interface SuperJSONObject {
  [key: string]: SuperJSONValue;
}

export interface SuperJSONResult {
  json: JSONValue;
  meta?: {
    values?: MinimisedTree<TypeAnnotation>;
    referentialEqualities?: ReferentialEqualityAnnotations;
    v?: number;
  };
}
=====CLASS REGISTRY=====
import { Registry } from './registry.js';
import { Class } from './types.js';

export interface RegisterOptions {
  identifier?: string;
  allowProps?: string[];
}

export class ClassRegistry extends Registry<Class> {
  constructor() {
    super(c => c.name);
  }

  private classToAllowedProps = new Map<Class, string[]>();

  register(value: Class, options?: string | RegisterOptions): void {
    if (typeof options === 'object') {
      if (options.allowProps) {
        this.classToAllowedProps.set(value, options.allowProps);
      }

      super.register(value, options.identifier);
    } else {
      super.register(value, options);
    }
